public static void main(String[] args) {
    ArrayList<Integer> ball = new ArrayList<Integer>();
    Scanner scan = new Scanner(System.in);

    int number = scan.nextInt();
    scan.nextLine();
    String inputs = scan.nextLine();
    String[] n = inputs.split(" ");
    ArrayList<Integer> inp = new ArrayList<Integer>();
    for (int i = 0; i < n.length; i++) {
        inp.add(Integer.parseInt(n[i]));
    }

    for (int k = 0; k < inp.size(); k++) {
        int addnumber = inp.get(k);
        ball.add(addnumber);

        while (ball.size() > 1 && ball.get(ball.size() - 1).equals(ball.get(ball.size() - 2))) {
            int last = ball.remove(ball.size() - 1);
            ball.remove(ball.size() - 1);
            ball.add(last + 1);
        }
    }

    System.out.println(ball.size());
}
